(() => {
 'use strict';
 const type=document.getElementById('contribute-type');
 const payment=document.getElementById('contribute-method');
 const campaign=document.getElementById('contribute-campaign');
 const ref=document.getElementById('contribute-ref');
 const name=document.getElementById('contribute-name');
 const proof=document.getElementById('contribute-proof');
 if(!type||!payment) return;
 const update=()=>{
   const needsCampaign=type.selectedOptions[0]?.dataset.campaign==='1';
   const needsRef=payment.selectedOptions[0]?.dataset.reference==='1';
   document.getElementById('contribute-campaign-field').hidden=!needsCampaign;
   document.getElementById('contribute-ref-field').hidden=!needsRef;
   if(campaign){
     [...campaign.options].forEach(option=>{
       if(!option.value)return;
       const allowed=!option.dataset.type||option.dataset.type===type.value;
       option.hidden=!allowed;option.disabled=!allowed;
     });
     if(campaign.selectedOptions[0]?.disabled)campaign.value='';
     campaign.required=needsCampaign;
   }
   if(ref)ref.required=needsRef;
   const needsName=type.selectedOptions[0]?.dataset.anonymous==='0';
   const needsProof=payment.selectedOptions[0]?.dataset.proof==='1';
   if(name)name.required=needsName;
   if(proof)proof.required=needsProof;
   const nameLabel=document.getElementById('contribute-name-optional');
   const proofLabel=document.getElementById('contribute-proof-optional');
   if(nameLabel)nameLabel.textContent=needsName?'*':'(opcional)';
   if(proofLabel)proofLabel.textContent=needsProof?'*':'(opcional)';
 };
 type.addEventListener('change',update);
 payment.addEventListener('change',update);
 update();
})();

/* Igreja Master 3.7.27 - correção visual de contraste.
 * Carregada DEPOIS das folhas legadas, evitando texto claro sobre branco.
 * Sidebar móvel permanece escura; desktop usa abas claras com texto escuro.
 */
@media screen and (min-width:1100px) {
  .sidebar .nav-list {
    background:#f8fbff!important;
    color:#173a64!important;
    border-bottom:1px solid #c9d9ec!important;
    box-shadow:0 2px 10px rgba(20,51,90,.08);
  }
  .sidebar .nav-list .nav-group {
    background:transparent;
    border-right:1px solid #dce7f3;
  }
  .sidebar .nav-list .nav-group>summary {
    background:transparent!important;
    color:#173c6b!important;
    font-weight:700!important;
    font-size:13px;
    opacity:1!important;
    text-shadow:none!important;
  }
  .sidebar .nav-list .nav-group>summary svg,
  .sidebar .nav-list .nav-group>summary span,
  .sidebar .nav-list .nav-group>summary .nav-chevron {
    color:#173c6b!important;
    opacity:1!important;
    stroke:currentColor;
  }
  .sidebar .nav-list .nav-group>summary:hover,
  .sidebar .nav-list .nav-group[open]>summary,
  .sidebar .nav-list .nav-group>summary:focus-visible {
    color:#0e3f7a!important;
    background:#e5f1ff!important;
    outline-offset:-3px;
  }
  .sidebar .nav-list .nav-group>summary:hover svg,
  .sidebar .nav-list .nav-group>summary:focus-visible svg,
  .sidebar .nav-list .nav-group[open]>summary svg {color:#0e3f7a!important;}
  .sidebar .nav-list .nav-group-links {
    background:#fff!important;
    border:1px solid #c7d7e8!important;
    box-shadow:0 14px 35px rgba(17,44,83,.18)!important;
    color:#173a64!important;
    z-index:200;
  }
  .sidebar .nav-list .nav-group-links .nav-item,
  .sidebar .nav-list .nav-group-links a {
    color:#1b446f!important;
    background:#fff!important;
    opacity:1!important;
    font-size:13px;
    font-weight:600;
  }
  .sidebar .nav-list .nav-group-links .nav-item:hover,
  .sidebar .nav-list .nav-group-links a:focus-visible {
    background:#e9f3ff!important;
    color:#093e7d!important;
  }
  .sidebar .nav-list .nav-group-links .nav-item.active,
  .sidebar .nav-list .nav-group-links .nav-item[aria-current="page"] {
    background:var(--church-primary,#0D47A1)!important;
    color:#fff!important;
    font-weight:700;
  }
  .sidebar .nav-list .nav-group-links .nav-item.active:after{
    background:#fff!important;
  }
}
@media screen and (max-width:1099px) {
  .sidebar .nav-list .nav-group>summary,
  .sidebar .nav-list .nav-group>summary svg,
  .sidebar .nav-list .nav-group>summary span {
    color:#f1f7ff!important;
    opacity:1!important;
    font-weight:650;
  }
  .sidebar .nav-list .nav-group-links .nav-item {
    color:#eaf4ff!important;
    opacity:1!important;
  }
  .sidebar .nav-list .nav-group-links .nav-item.active {
    background:var(--church-primary,#0D47A1)!important;
    color:#fff!important;
  }
}

/* Igreja Master 3.7.27 - Conferência financeira completa */
.finance-gov-layout{display:grid;grid-template-columns:minmax(270px,.78fr) minmax(0,1.42fr);gap:18px;align-items:start}
.finance-gov-layout>.card{min-width:0}
.finance-gov-layout .card h3,.finance-gov-section h3{font-size:15px;color:#123e72;margin:26px 0 14px;border-bottom:1px solid #dce8f4;padding-bottom:9px}
.finance-gov-queue{display:grid;gap:8px;max-height:370px;overflow-y:auto;margin-top:12px}
.finance-gov-link{display:flex;gap:12px;justify-content:space-between;align-items:center;text-decoration:none;padding:12px;border:1px solid #dbe7f4;background:#fff;border-radius:10px;color:#153d67;font-size:12px}
.finance-gov-link small,.finance-gov-link strong{display:block}.finance-gov-link small{font-size:11px;color:#607c99;margin-top:5px}
.finance-gov-link.selected,.finance-gov-link:hover{border-color:var(--church-secondary,#1976D2);background:#ecf5ff}
.finance-gov-heading{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;margin-bottom:18px}
.finance-gov-heading h2{font-size:19px;margin:4px 0 0;color:#163e70}
.finance-gov-heading p{font-size:11px;overflow-wrap:anywhere}
.finance-gov-status{display:inline-flex;border-radius:20px;padding:7px 10px;background:#e8f2ff;color:#0d458a;font-size:11px;font-weight:800;letter-spacing:.03em}
.finance-gov-money{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:14px 0 22px}
.finance-gov-money>div{border:1px solid #d7e8f8;border-radius:12px;background:#f2f8ff;padding:15px}
.finance-gov-money small,.finance-gov-money strong{display:block}
.finance-gov-money small{font-size:11px;color:#567693}
.finance-gov-money strong{font-size:19px;color:#123d70;margin-top:6px}
.finance-gov-form{border-top:1px solid #e1eaf5;padding:16px 0 22px;display:grid;gap:13px}
.finance-gov-form h3{margin:8px 0 4px!important}
.finance-gov-form .field,.finance-gov-inline .field{display:grid;gap:6px;min-width:0}
.finance-gov-form label,.finance-gov-inline label{font-size:12px;color:#1c406f;font-weight:670}
.finance-gov-form output{display:flex;align-items:center;min-height:45px;padding:10px 14px;border-radius:10px;background:#e9f5ee;color:#14633f;font-weight:800}
.finance-gov-form button{justify-self:start;min-height:44px}
.finance-gov-checks{display:grid;gap:8px}.finance-gov-checks label{display:flex;align-items:center;gap:10px;line-height:1.5}
.finance-gov-checks input{accent-color:var(--church-primary);width:18px;height:18px;flex:0 0 auto}
.finance-gov-history{background:#f8fbff;border:1px solid #e2eaf5;border-radius:10px;padding:12px 16px;max-height:360px;overflow:auto}
.finance-gov-history p{color:#4e6b8b;font-size:12px;line-height:1.5;border-bottom:1px solid #e9f0f9;padding-bottom:8px}
.finance-gov-section{margin-top:22px}
.finance-gov-inline{display:flex;align-items:end;flex-wrap:wrap;gap:10px;margin:14px 0 19px}
.finance-gov-inline .field{min-width:145px;flex:1}
.finance-gov-inline input[type=checkbox]{width:18px;height:18px;accent-color:var(--church-primary);vertical-align:middle}
.finance-gov-inline label:has(input[type=checkbox]){max-width:240px;align-self:center}
.finance-gov-inline .btn{min-height:44px}
@media(max-width:1040px){.finance-gov-layout{grid-template-columns:1fr}.finance-gov-layout>.card:first-child{order:0}}
@media(max-width:620px){.finance-gov-money{grid-template-columns:1fr}.finance-gov-money>div{padding:12px}.finance-gov-money strong{font-size:17px}.finance-gov-form button{width:100%}.finance-gov-inline .field{flex-basis:100%}.finance-gov-inline button{width:100%}}

/* Ajuste de valores e campos fiscais do formulário sem alterar dados do servidor */
(() => {
  'use strict';
  const form=document.getElementById('finance-gov-classification');
  if(!form)return;
  const gross=form.querySelector('[name="gross_amount"]');
  const fee=form.querySelector('[name="fees_amount"]');
  const output=document.getElementById('finance-gov-net');
  const docs=document.getElementById('finance-gov-document');
  const money=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'});
  function cents(value){
    const s=String(value??'').trim().replace(/R\$\s*/g,'').replace(/\s+/g,'');
    const normalized=/^\d{1,3}(\.\d{3})+(,\d{1,2})?$/.test(s)?s.replaceAll('.','').replace(',','.'):
      /^\d{1,10}(,\d{1,2})?$/.test(s)?s.replace(',',''):s;
    if(!/^\d{1,10}(\.\d{1,2})?$/.test(normalized))return null;
    const n=Number(normalized);
    return Number.isFinite(n)?Math.round(n*100):null;
  }
  function recalc(){
    if(!output)return;
    const b=cents(gross?.value),f=cents(fee?.value);
    if(b===null||f===null||f>b){output.textContent='Verifique os valores';output.style.color='#a22b38';return;}
    output.textContent=money.format((b-f)/100);output.style.color='';
  }
  [gross,fee].forEach(el=>el?.addEventListener('input',recalc));
  function validateDocument(){
    const selected=docs?.selectedOptions[0];
    for(const [name,key] of [['document_number','number'],['document_date','date'],['access_key','key']]){
       const input=form.querySelector('[name="'+name+'"]');
       if(input)input.required=selected?.dataset[key]==='1';
    }
  }
  docs?.addEventListener('change',validateDocument);
  form.addEventListener('submit',e=>{
    const b=cents(gross?.value),f=cents(fee?.value);
    if(b===null||b<=0||f===null||f<0||f>b){
       e.preventDefault();gross?.setCustomValidity('Bruto deve ser positivo e taxa deve estar entre zero e bruto.');
       gross?.reportValidity();return;
    }
    gross?.setCustomValidity('');
    validateDocument();
  });
  validateDocument();recalc();
})();
